import{_ as r,l as t,o as a,c,v as o,p as s,x as l,d as i,i as n,S as x}from"./chunks/framework.InCnrqk-.js";const T=JSON.parse('{"title":"lex / flex","description":"","frontmatter":{"title":"lex / flex","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/lex-flex.md","filePath":"cs/lex-flex.md","lastUpdated":1789023840000}'),p={name:"cs/lex-flex.md"};function f(h,e,m,_,u,A){const d=t("Mermaid");return a(),c("div",null,[e[1]||(e[1]=o('<h1 id="lex-flex" tabindex="-1">lex / flex <a class="header-anchor" href="#lex-flex" aria-label="Permalink to &quot;lex / flex&quot;">​</a></h1><div class="epigraph"><p>规则写成正则与动作；生成器交出一张表驱动的扫描器，而不是让人在源码里手画全部转移。</p><footer>—— 据 Lesk and Schmidt, Lex — A Lexical Analyzer Generator；Levine, Flex &amp; Bison；龙书第 3 章整理</footer></div><p>上一课<a href="/cs/word-ram">word RAM</a>把算法进阶收到字模型与位并行。本课起「程序语言与编译进阶」：主干已会<a href="/cs/regex-lexer">正则与词法</a>、<a href="/cs/nfa-dfa">NFA 与 DFA</a>、<a href="/cs/thompson-nfa">Thompson 构造</a>，缺口不是再证正则等于有穷自动机，而是<strong>生成器</strong>——lex / flex 如何把规则文件编译成扫描函数。后课默认已经读完本课：词法规则进 <code>.l</code>，动作吐记号，冲突按最长匹配与表序消解。不重写 Transformer，不进限价簿。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>手写 DFA 能切标识符，一改关键字表就要改状态图。lex 的输入是「模式–动作」对：模式是正则，动作是嵌入的 C（或等价宿主）。生成期：规则并成 NFA，确定化、压缩成表；运行期：<code>yylex</code> 读字符，走表，匹配成功执行动作。缺口是这份<strong>规则编译</strong>，不是再定义 lexeme。</p><p>与证明助手无关的是实现层：扫描器必须终止、必须对源长近似线性；lex 把「会不会写错转移」从人挪到生成器。进阶课从这里接主干前端，不重开 λ 的 β。</p><h3 id="规则表不是-cfg" tabindex="-1">规则表不是 CFG <a class="header-anchor" href="#规则表不是-cfg" aria-label="Permalink to &quot;规则表不是 CFG&quot;">​</a></h3><p><code>if</code> 与标识符的冲突由最长匹配和规则先后决定，不是移进归约。括号嵌套仍不是正则；flex 的起始条件（<code>%x COMMENT</code>）只是有限个词法模式，数不了任意层嵌套语法。</p><p><span class="marginnote">Lesk 的 lex 与 GNU flex 是同一契约的实现。龙书把生成器当词法章的工程落地。本课不把 Unicode 标识符写完，那是本课序末尾的编码课。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>写 <code>.l</code>：定义段、<code>%%</code>、规则、用户子程序。动作里 <code>return TOK</code>，<code>yytext</code>/<code>yyleng</code> 指向本次 lexeme。关键字可写进规则，或标识符之后查表覆写——与主干词法课同一约定，这里由生成器保证最长者胜。</p>',11)),(a(),s(x,null,{default:l(()=>[n(d,{id:"mermaid-31",class:"mermaid",graph:"flowchart%20TD%0A%20%20RULE%5B%22%E8%A7%84%E5%88%99%E6%96%87%E4%BB%B6%20.l%22%5D%20--%3E%20GEN%5B%22lex%20%2F%20flex%20%E7%94%9F%E6%88%90%22%5D%0A%20%20GEN%20--%3E%20TBL%5B%22DFA%20%E8%A1%A8%20%2B%20yylex%22%5D%0A%20%20TBL%20--%3E%20TOK%5B%22%E8%AE%B0%E5%8F%B7%E6%B5%81%22%5D%0A"})]),fallback:l(()=>[...e[0]||(e[0]=[i(" Loading... ",-1)])]),_:1})),e[2]||(e[2]=o('<p>调试冲突：flex 的 <code>--debug</code> 与规则编号；同长度时看规则在文件中的次序。不要在动作里再扫描字符绕过 DFA，那会毁掉行号与位置。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>表压缩（行压缩、等价类）降低缓存压力，不改变语言。回溯：最长匹配要记住最后接受态，失败则回退输入指针——这是词法约定，不是 NFA 的 ε。flex 的 <code>REJECT</code> 会重试次长匹配，代价高，进阶课点名即可，默认不用。</p><p>与 yacc 对接：<code>yylex</code> 的返回值是记号种别，<code>yylval</code> 带语义值。本课只保证扫描器接口；语法生成器下一课。</p><p>起始条件把注释、字符串字面量从「一个大正则」里拆成模式机：进入 <code>COMMENT</code> 后只认注释内规则，直到 <code>*/</code>。这仍是有穷状态，不是下推。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不写 bison 的产生式，不处理 GLR。不把 flex 的全部选项当手册抄录。后课默认：词法由生成器从正则规则得出；语法的输入是 <code>yylex</code> 的记号。下一课用同一风格接 yacc / bison。</p><p>生成器吃正则，不吃任意 CFG。源编码、宏展开会在词法前后插刀，本课序后段再补；此处假定字节或已规范化的字符流。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>lex / flex：正则规则编译成表驱动 <code>yylex</code>。</li><li>冲突：最长匹配，其次规则序；不是 LR 冲突。</li><li>与主干词法课同一分工：记号正则、嵌套归语法。</li><li>出处：Lesk and Schmidt；Levine, <em>Flex &amp; Bison</em>；Aho et al., 龙书第 3 章。</li></ul>',10))])}const y=r(p,[["render",f]]);export{T as __pageData,y as default};
